const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([-114.614, 34.848]); // Needles, CA
    const region = point.buffer(10000); // 10 km buffer to capture grid cell(s)
    const start = ee.Date('2017-06-15');
    const end = ee.Date('2017-06-22'); // exclusive, covers 15–21
    const band = 'temperature_2m';
    let datasetId = 'ECMWF/ERA5_LAND/HOURLY';

    // 2. Data Acquisition & Check
    let col = ee.ImageCollection(datasetId).filterDate(start, end).select(band);
    let size;
    try {
      size = await col.size().getInfo();
    } catch (e) {
      console.log('Dataset error on primary:', e.toString());
      console.log('D');
      return;
    }
    if (size === 0) {
      // Fallback to full ERA5 if LAND has no images (unlikely)
      datasetId = 'ECMWF/ERA5/HOURLY';
      col = ee.ImageCollection(datasetId).filterDate(start, end).select(band);
      try {
        size = await col.size().getInfo();
      } catch (e2) {
        console.log('Dataset error on fallback:', e2.toString());
        console.log('D');
        return;
      }
      if (size === 0) {
        console.log('Images (hrs): 0');
        console.log('C1');
        return;
      }
    }

    console.log(`Location: Needles, CA (-114.614, 34.848), radius 10 km`);
    console.log(`Date range: 2017-06-15 to 2017-06-21 (inclusive)`);
    console.log(`Dataset: ${datasetId}`);
    console.log(`Images (hrs): ${size}`);

    // 3. Processing & Pixel Validation
    const imgMaxTime = col.max(); // per-pixel max across time window
    const count = await ee.Number(
      imgMaxTime.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 3000,
        maxPixels: 1e9
      }).get(band)
    ).getInfo();

    if (!count || count === 0) {
      console.log('Valid pixels (count@3km): 0');
      console.log('C2');
      return;
    }
    console.log(`Valid pixels (count@3km): ${count}`);

    // 4. Calculation: Max temperature over the window
    const maxK = await ee.Number(
      imgMaxTime.reduceRegion({
        reducer: ee.Reducer.max(),
        geometry: region,
        scale: 3000,
        maxPixels: 1e9
      }).get(band)
    ).getInfo();

    if (maxK === null || isNaN(maxK)) {
      console.log('Max T2m: null');
      console.log('C3');
      return;
    }
    const maxF = (maxK - 273.15) * 9 / 5 + 32;
    if (maxF < -100 || maxF > 150) {
      console.log(`Max T2m (F): ${maxF.toFixed(1)} (out of plausible range)`);
      console.log('C3');
      return;
    }
    console.log(`Period Max T2m: ${maxF.toFixed(1)} °F (${maxK.toFixed(2)} K)`);

    // 5. Daily maxima for evidence
    const nDays = await end.difference(start, 'day').getInfo();
    for (let d = 0; d < nDays; d++) {
      const dStart = start.advance(d, 'day');
      const dEnd = dStart.advance(1, 'day');
      const label = await dStart.format('YYYY-MM-dd').getInfo();
      const dayCol = col.filterDate(dStart, dEnd);
      const daySize = await dayCol.size().getInfo();
      let dayMaxFStr = 'null';
      if (daySize > 0) {
        const dayMaxImg = dayCol.max();
        const dayMaxK = await ee.Number(
          dayMaxImg.reduceRegion({
            reducer: ee.Reducer.max(),
            geometry: region,
            scale: 3000,
            maxPixels: 1e9
          }).get(band)
        ).getInfo();
        if (dayMaxK !== null && !isNaN(dayMaxK)) {
          const dayMaxF = (dayMaxK - 273.15) * 9 / 5 + 32;
          dayMaxFStr = `${dayMaxF.toFixed(1)}`;
        }
      }
      console.log(`${label}: max ${dayMaxFStr} °F (hrs: ${daySize})`);
    }

    // 6. Final Answer
    const reached115 = maxF >= 115.0;
    console.log(reached115 ? 'A' : 'B');
  } catch (err) {
    console.log('Error:', err.toString());
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
